INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','verb-pattern-meaning','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"verb-pattern-meaning","title":"Verb patterns that change meaning","level":"B2","order":54,"summary":"Distinguish remembering a duty from recalling an experience, stopping an action from pausing for a purpose, and methods from attempts.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Remember a duty or recall an experience","Stop one activity or pause for another","Try a method or attempt a difficult action","Go on and regret"],"rules":[{"title":"Remember a duty or recall an experience","explanation":"**Remember to do** means remembering a necessary action before doing it. **Remember doing** means recalling an earlier experience. The same contrast often appears with forget, although a negative such as I’ll never forget meeting her is especially common.","pattern":"Remember **to lock** the door. / I remember **locking** it.","commonMistakes":["The -ing form refers to the remembered experience; it is not simply an alternative spelling of the infinitive."],"examples":["The task is still ahead. Complete the reminder: “Please remember **to prepare** the visitor guide.”","The task is still ahead. Complete the reminder: “Please remember **to restore** the old portrait.”"],"skill":"form"},{"title":"Stop one activity or pause for another","explanation":"**Stop doing** means cease that activity. **Stop to do** means interrupt another activity in order to do this one. The second pattern is an infinitive of purpose, so it answers why the person paused.","pattern":"We stopped **talking**. / We stopped **to talk**.","commonMistakes":["Stopped to smoke does not mean quit smoking; it means paused in order to smoke."],"examples":["The task happened yesterday and I recall doing it: “I remember **preparing** the visitor guide.”","The task happened yesterday and I recall doing it: “I remember **restoring** the old portrait.”"],"skill":"meaning"},{"title":"Try a method or attempt a difficult action","explanation":"**Try doing** often suggests testing a method to see if it helps. **Try to do** emphasises making an attempt, which may fail. Some contexts allow both with little practical difference, so tasks need a clear intention.","pattern":"Try **restarting** it. / I tried **to lift** it but could not.","commonMistakes":["Do not assume that try + -ing always succeeded; it describes the method being tested."],"examples":["They ceased this activity completely: “They stopped **preparing** the visitor guide.”","They ceased this activity completely: “They stopped **restoring** the old portrait.”"],"skill":"contrast"},{"title":"Go on and regret","explanation":"Go on doing continues the same activity; go on to do moves to a new activity. Regret doing looks back with regret, while regret to inform is a conventional way to introduce unwelcome information. Learn these as meaning-and-form pairs.","pattern":"She went on **speaking**. / She went on **to explain** the next step.","commonMistakes":["Not every verb accepts both patterns. Avoid transferring these contrasts to verbs such as enjoy, which normally takes -ing."],"examples":["We interrupted our walk in order to do the task: “We stopped **to prepare** the visitor guide.”","We interrupted our walk in order to do the task: “We stopped **to restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"a1483e91-1c11-5d95-a20f-2e1c2de7f5d4","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task is still ahead. Complete the reminder: “Please remember ____ the visitor guide.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepared"},{"id":"C","text":"to prepare"},{"id":"D","text":"preparing"}],"answerId":"C","hint":"Locate the task in time: it is a **future duty**, not a memory.","explanation":"**Remember to prepare** means remember the duty before carrying it out.","keywords":["remember-future-duty"],"skill":"remember-future-duty","contextKey":"verb-pattern-meaning-1","fingerprint":"6b4a2ef66929b4f0dbe3743dadb9b68623459fe16ded2223659163c8e0178014","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate the task in time: it is a **future duty**, not a memory.","**Remember to prepare** means remember the duty before carrying it out.","Choose **to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Remember normally needs a to-infinitive for this duty meaning.","B":"A past form does not supply the required complement.","C":"**Remember to prepare** means remember the duty before carrying it out.","D":"Remember + -ing recalls an earlier experience; the task is still ahead."}}},{"id":"98d44e90-9fea-5e45-a6ba-6e2bc451dcae","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task happened yesterday and I recall doing it: “I remember ____ the visitor guide.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"to prepare"},{"id":"C","text":"prepare"},{"id":"D","text":"prepared"}],"answerId":"A","hint":"The speaker is **recalling an experience that already happened**.","explanation":"**Remember preparing** recalls the earlier experience explicitly described.","keywords":["remember-past-experience"],"skill":"remember-past-experience","contextKey":"verb-pattern-meaning-1","fingerprint":"79d9a5f5b8c73b8696698f0d58e2fd02fe16236a591f54f16d5d673d312fc0db","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The speaker is **recalling an experience that already happened**.","**Remember preparing** recalls the earlier experience explicitly described.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Remember preparing** recalls the earlier experience explicitly described.","B":"Remember to points to remembering a duty before doing it, rather than recalling the experience now.","C":"A base verb without to does not form this complement.","D":"The past form is not the required -ing complement."}}},{"id":"f5b6ceb9-46cd-5232-ae88-b10bbc95b7ba","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"They ceased this activity completely: “They stopped ____ the visitor guide.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"preparing"},{"id":"C","text":"to prepare"},{"id":"D","text":"prepare"}],"answerId":"B","hint":"The activity itself **ended**; this is stop + -ing.","explanation":"**Stopped preparing** means they ceased that activity.","keywords":["stop-ceasing"],"skill":"stop-ceasing","contextKey":"verb-pattern-meaning-1","fingerprint":"a5ca70b565990b9ad0aedd9be525685f38bbc9c30be42385cd8b1ef80b393221","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The activity itself **ended**; this is stop + -ing.","**Stopped preparing** means they ceased that activity.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past form cannot serve as this complement.","B":"**Stopped preparing** means they ceased that activity.","C":"Stopped to would mean paused another activity in order to do this one.","D":"Stop cannot take a bare base verb for this meaning."}}},{"id":"ddc1a794-1542-5618-a0b4-162ec3777f34","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"We interrupted our walk in order to do the task: “We stopped ____ the visitor guide.”","choices":[{"id":"A","text":"to prepare"},{"id":"B","text":"preparing"},{"id":"C","text":"prepare"},{"id":"D","text":"prepared"}],"answerId":"A","hint":"The blank answers **why we paused another activity**.","explanation":"**Stopped to prepare** gives the purpose of pausing the walk.","keywords":["stop-purpose"],"skill":"stop-purpose","contextKey":"verb-pattern-meaning-1","fingerprint":"63a2ece275d1ebcbad09f68d6f82ec7fb8eab9de5910b0c95b97ad14ec02527c","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The blank answers **why we paused another activity**.","**Stopped to prepare** gives the purpose of pausing the walk.","Choose **to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Stopped to prepare** gives the purpose of pausing the walk.","B":"Stopped + -ing would mean we ceased this task, not paused the walk to begin it.","C":"A purpose infinitive needs to.","D":"A past form does not express the purpose of stopping."}}},{"id":"a2f353fb-85ce-5bcb-a64a-9288c356986c","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task is still ahead. Complete the reminder: “Please remember ____ the old portrait.”","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restored"},{"id":"C","text":"to restore"},{"id":"D","text":"restoring"}],"answerId":"C","hint":"Locate the task in time: it is a **future duty**, not a memory.","explanation":"**Remember to restore** means remember the duty before carrying it out.","keywords":["remember-future-duty"],"skill":"remember-future-duty","contextKey":"verb-pattern-meaning-2","fingerprint":"73caf032072ad8c82079a781b666ed98878dd3f228a9e5e5431ce4c6109b0421","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate the task in time: it is a **future duty**, not a memory.","**Remember to restore** means remember the duty before carrying it out.","Choose **to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Remember normally needs a to-infinitive for this duty meaning.","B":"A past form does not supply the required complement.","C":"**Remember to restore** means remember the duty before carrying it out.","D":"Remember + -ing recalls an earlier experience; the task is still ahead."}}},{"id":"90b10951-c369-5d78-af1c-d1bad4c2a20e","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task happened yesterday and I recall doing it: “I remember ____ the old portrait.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restored"}],"answerId":"A","hint":"The speaker is **recalling an experience that already happened**.","explanation":"**Remember restoring** recalls the earlier experience explicitly described.","keywords":["remember-past-experience"],"skill":"remember-past-experience","contextKey":"verb-pattern-meaning-2","fingerprint":"28de1f30a96361417910bd355d53c9cf52dbd7c97b2868d947bb03cbb68fea45","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The speaker is **recalling an experience that already happened**.","**Remember restoring** recalls the earlier experience explicitly described.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Remember restoring** recalls the earlier experience explicitly described.","B":"Remember to points to remembering a duty before doing it, rather than recalling the experience now.","C":"A base verb without to does not form this complement.","D":"The past form is not the required -ing complement."}}},{"id":"b7ab68b2-986b-5c26-aceb-ad14ab831c66","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"They ceased this activity completely: “They stopped ____ the old portrait.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"to restore"},{"id":"C","text":"restore"},{"id":"D","text":"restored"}],"answerId":"A","hint":"The activity itself **ended**; this is stop + -ing.","explanation":"**Stopped restoring** means they ceased that activity.","keywords":["stop-ceasing"],"skill":"stop-ceasing","contextKey":"verb-pattern-meaning-2","fingerprint":"b6f3a38d232d5695723a0661bc4c50c5c199194b8b60132043c76c147846abd5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The activity itself **ended**; this is stop + -ing.","**Stopped restoring** means they ceased that activity.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Stopped restoring** means they ceased that activity.","B":"Stopped to would mean paused another activity in order to do this one.","C":"Stop cannot take a bare base verb for this meaning.","D":"A past form cannot serve as this complement."}}},{"id":"35db53e1-b953-5237-ad49-94ea95a64ac5","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"We interrupted our walk in order to do the task: “We stopped ____ the old portrait.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restoring"},{"id":"C","text":"restore"},{"id":"D","text":"restored"}],"answerId":"A","hint":"The blank answers **why we paused another activity**.","explanation":"**Stopped to restore** gives the purpose of pausing the walk.","keywords":["stop-purpose"],"skill":"stop-purpose","contextKey":"verb-pattern-meaning-2","fingerprint":"bd55031f7dce6a7b77587e4f692ff46e1ca354a2b7efefd4e56421766a7601cb","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The blank answers **why we paused another activity**.","**Stopped to restore** gives the purpose of pausing the walk.","Choose **to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Stopped to restore** gives the purpose of pausing the walk.","B":"Stopped + -ing would mean we ceased this task, not paused the walk to begin it.","C":"A purpose infinitive needs to.","D":"A past form does not express the purpose of stopping."}}},{"id":"ac9b2fc5-4eeb-5295-a689-4bb1dce0546d","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task is still ahead. Complete the reminder: “Please remember ____ the garden fence.”","choices":[{"id":"A","text":"measure"},{"id":"B","text":"measured"},{"id":"C","text":"to measure"},{"id":"D","text":"measuring"}],"answerId":"C","hint":"Locate the task in time: it is a **future duty**, not a memory.","explanation":"**Remember to measure** means remember the duty before carrying it out.","keywords":["remember-future-duty"],"skill":"remember-future-duty","contextKey":"verb-pattern-meaning-3","fingerprint":"b213b02b7e7c08417f940f11c69a829c85c5bb7725d9b3bb1f30e7e5c4c14870","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate the task in time: it is a **future duty**, not a memory.","**Remember to measure** means remember the duty before carrying it out.","Choose **to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Remember normally needs a to-infinitive for this duty meaning.","B":"A past form does not supply the required complement.","C":"**Remember to measure** means remember the duty before carrying it out.","D":"Remember + -ing recalls an earlier experience; the task is still ahead."}}},{"id":"c025141b-a779-55d9-a361-a3701ea95b93","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task happened yesterday and I recall doing it: “I remember ____ the garden fence.”","choices":[{"id":"A","text":"measured"},{"id":"B","text":"measuring"},{"id":"C","text":"to measure"},{"id":"D","text":"measure"}],"answerId":"B","hint":"The speaker is **recalling an experience that already happened**.","explanation":"**Remember measuring** recalls the earlier experience explicitly described.","keywords":["remember-past-experience"],"skill":"remember-past-experience","contextKey":"verb-pattern-meaning-3","fingerprint":"147ffc43f3d792f5abb339135ef6a729bb874b79e1741fa98ea8e80724b7970a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The speaker is **recalling an experience that already happened**.","**Remember measuring** recalls the earlier experience explicitly described.","Choose **measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The past form is not the required -ing complement.","B":"**Remember measuring** recalls the earlier experience explicitly described.","C":"Remember to points to remembering a duty before doing it, rather than recalling the experience now.","D":"A base verb without to does not form this complement."}}},{"id":"e73eeae0-685d-550a-a66e-c9eaaed53104","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"They ceased this activity completely: “They stopped ____ the garden fence.”","choices":[{"id":"A","text":"to measure"},{"id":"B","text":"measure"},{"id":"C","text":"measured"},{"id":"D","text":"measuring"}],"answerId":"D","hint":"The activity itself **ended**; this is stop + -ing.","explanation":"**Stopped measuring** means they ceased that activity.","keywords":["stop-ceasing"],"skill":"stop-ceasing","contextKey":"verb-pattern-meaning-3","fingerprint":"fc83e818e8646ec2ceefa1564b2b840c04d15d7f9ba655c87094dc9982339a0d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The activity itself **ended**; this is stop + -ing.","**Stopped measuring** means they ceased that activity.","Choose **measuring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Stopped to would mean paused another activity in order to do this one.","B":"Stop cannot take a bare base verb for this meaning.","C":"A past form cannot serve as this complement.","D":"**Stopped measuring** means they ceased that activity."}}},{"id":"1815934b-d352-5929-a5e9-532b58a03451","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"We interrupted our walk in order to do the task: “We stopped ____ the garden fence.”","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"measure"},{"id":"C","text":"measured"},{"id":"D","text":"to measure"}],"answerId":"D","hint":"The blank answers **why we paused another activity**.","explanation":"**Stopped to measure** gives the purpose of pausing the walk.","keywords":["stop-purpose"],"skill":"stop-purpose","contextKey":"verb-pattern-meaning-3","fingerprint":"637de5785b63c8e6befaa11c6ce3ec67ebcd583ee4f35be51c0400282fb770b4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The blank answers **why we paused another activity**.","**Stopped to measure** gives the purpose of pausing the walk.","Choose **to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Stopped + -ing would mean we ceased this task, not paused the walk to begin it.","B":"A purpose infinitive needs to.","C":"A past form does not express the purpose of stopping.","D":"**Stopped to measure** gives the purpose of pausing the walk."}}},{"id":"d526f797-023e-5ac4-af18-6de54af5741f","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task is still ahead. Complete the reminder: “Please remember ____ the travel leaflet.”","choices":[{"id":"A","text":"to translate"},{"id":"B","text":"translating"},{"id":"C","text":"translate"},{"id":"D","text":"translated"}],"answerId":"A","hint":"Locate the task in time: it is a **future duty**, not a memory.","explanation":"**Remember to translate** means remember the duty before carrying it out.","keywords":["remember-future-duty"],"skill":"remember-future-duty","contextKey":"verb-pattern-meaning-4","fingerprint":"85770964439268473d6d8b1440807e1920ed94d26d07cf245e583875935f9435","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Locate the task in time: it is a **future duty**, not a memory.","**Remember to translate** means remember the duty before carrying it out.","Choose **to translate**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Remember to translate** means remember the duty before carrying it out.","B":"Remember + -ing recalls an earlier experience; the task is still ahead.","C":"Remember normally needs a to-infinitive for this duty meaning.","D":"A past form does not supply the required complement."}}},{"id":"4a03e05f-d671-5225-a6f9-fec3c2c09aee","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"The task happened yesterday and I recall doing it: “I remember ____ the travel leaflet.”","choices":[{"id":"A","text":"translate"},{"id":"B","text":"translated"},{"id":"C","text":"translating"},{"id":"D","text":"to translate"}],"answerId":"C","hint":"The speaker is **recalling an experience that already happened**.","explanation":"**Remember translating** recalls the earlier experience explicitly described.","keywords":["remember-past-experience"],"skill":"remember-past-experience","contextKey":"verb-pattern-meaning-4","fingerprint":"15c77a8f95be925a9093ea3c2aa14144b76e45a1bb9d37a8f39624918ea9e639","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-verb-meaning"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The speaker is **recalling an experience that already happened**.","**Remember translating** recalls the earlier experience explicitly described.","Choose **translating**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A base verb without to does not form this complement.","B":"The past form is not the required -ing complement.","C":"**Remember translating** recalls the earlier experience explicitly described.","D":"Remember to points to remembering a duty before doing it, rather than recalling the experience now."}}},{"id":"4dda4efe-014b-52e6-a06d-8cb6ab945da0","topicSlug":"verb-pattern-meaning","level":"B2","prompt":"They ceased this activity completely: “They stopped ____ the travel leaflet.”","choices":[{"id":"A","text":"translate"},{"id":"B","text":"translated"},{"id":"C","text":"translating"},{"id":"D","text":"to translate"}],"answerId":"C","hint":"The activity itself **ended*